% Problem: Tightening ode45's Tolerances for a Fast-Decaying Signal
% Name:
% Date:

clear; clc;

f = @(t, V) -5 * V;
V0 = 10;
tspan = [0 3];

% a) Solve with default tolerances -> t1, V1; display length(t1)


% b) Build options with odeset; solve again -> t2, V2; display length(t2)


% c) Compare V1(end) and V2(end); one-line comment

solutionCode:
f = @(t, V) -5 * V;
V0 = 10;
tspan = [0 3];

% a) Default tolerances
[t1, V1] = ode45(f, tspan, V0);
disp(length(t1))

% b) Tightened tolerances via odeset
options = odeset('RelTol', 1e-8, 'AbsTol', 1e-10);
[t2, V2] = ode45(f, tspan, V0, options);
disp(length(t2))

% c) Compare final values
finalDiff = abs(V1(end) - V2(end));
disp(finalDiff)
% For this simple, well-behaved decay, tightening the tolerance barely
% changes the final answer -- the default tolerance was already accurate
% enough, it just took the solver more (smaller) steps to get there.

k1 = 0.6; k2 = 0.4;

% a) Parameterized three-compartment ODE handle
f = @(t, s, k3) [-k1 * s(1); ...                      % dgut/dt
                  k1 * s(1) - k2 * s(2); ...           % dblood/dt
                  k2 * s(2) - k3 * s(3)];               % dtissue/dt

% b) Normal renal function
fNormal = @(t, s) f(t, s, 0.25);
tspan = [0 24];
s0 = [100; 0; 0];
[t_h, s_h] = ode45(fNormal, tspan, s0);

% c) Impaired renal function
fImpaired = @(t, s) f(t, s, 0.05);
[t_i, s_i] = ode45(fImpaired, tspan, s0);

% d) Plot tissue compartment for both
figure
plot(t_h, s_h(:,3), 'b-', 'LineWidth', 1.5)
hold on
plot(t_i, s_i(:,3), 'r-', 'LineWidth', 1.5)
hold off
xlabel('Time (hr)')
ylabel('Tissue drug amount (mg)')
legend('Normal renal function', 'Impaired renal function', 'Location', 'best')
title('Tissue Drug Accumulation: Normal vs Impaired Renal Function')

% e) Peak tissue amount and time for each patient
[peakH, idxH] = max(s_h(:,3));
[peakI, idxI] = max(s_i(:,3));
fprintf('Normal: peak tissue = %.2f mg at t = %.2f hr\n', peakH, t_h(idxH));
fprintf('Impaired: peak tissue = %.2f mg at t = %.2f hr\n', peakI, t_i(idxI));

a = 0.15; b = 0.75; I = 0.55;

% a) Parameterized ODE handle
f = @(t, s, eps) [s(1) - s(1)^3/3 - s(2) + I; ...   % dv/dt
                   eps * (s(1) + a - b * s(2))];    % dw/dt

% b) Untreated neuron
fUntreated = @(t, s) f(t, s, 0.06);
tspan = [0 200];
s0 = [0; 0];
[t1, s1] = ode45(fUntreated, tspan, s0);

% c) Treated neuron (faster recovery)
fTreated = @(t, s) f(t, s, 0.10);
[t2, s2] = ode45(fTreated, tspan, s0);

% d) Plot v(t) for both
figure
plot(t1, s1(:,1), 'b-')
hold on
plot(t2, s2(:,1), 'r-')
hold off
xlabel('Time (ms)')
ylabel('Voltage v')
legend('Untreated', 'Treated', 'Location', 'best')
title('FitzHugh-Nagumo Spiking: Untreated vs Treated')

% e) Count spikes in each trace
v1 = s1(:,1); v2 = s2(:,1);
spikes1 = sum(islocalmax(v1) & v1 > 0);
spikes2 = sum(islocalmax(v2) & v2 > 0);
fprintf('Untreated spikes: %d\n', spikes1);
fprintf('Treated spikes: %d\n', spikes2);

% a) Parameterized ODE handle
f = @(t, s, Si) [-0.3 * s(1) - Si * s(2); ...   % dg/dt
                  0.4 * s(1) - 0.2 * s(2)];      % di/dt

% b) Healthy sensitivity
fHealthy = @(t, s) f(t, s, 0.5);
tspan = [0 20];
s0 = [50; 0];
[t_h, s_h] = ode45(fHealthy, tspan, s0);

% c) Reduced sensitivity
fResistant = @(t, s) f(t, s, 0.15);
[t_r, s_r] = ode45(fResistant, tspan, s0);

% d) Plot glucose for both
figure
plot(t_h, s_h(:,1), 'b-', 'LineWidth', 1.5)
hold on
plot(t_r, s_r(:,1), 'r-', 'LineWidth', 1.5)
hold off
xlabel('Time (hr)')
ylabel('Glucose deviation from baseline')
legend('Healthy sensitivity', 'Reduced sensitivity', 'Location', 'best')
title('Effect of Insulin Sensitivity on Glucose Response')

% e) Minimum glucose value for each
[minH, ~] = min(s_h(:,1));
[minR, ~] = min(s_r(:,1));
fprintf('Healthy minimum glucose deviation: %.2f\n', minH);
fprintf('Reduced-sensitivity minimum glucose deviation: %.2f\n', minR);

% a) ODE handle
f = @(t, s) [20 * s(1) - 3 * s(1)^2 - s(1) * s(2); ...   % ds1/dt
             25 * s(2) - 3 * s(2)^2 - s(1) * s(2)];       % ds2/dt
s0 = [3; 1.5];
tspan = [0 2000];

% b) Solve with ode45
tic
[t45, s45] = ode45(f, tspan, s0);
time45 = toc;
fprintf('ode45: %.4f s, %d points\n', time45, length(t45));

% c) Solve with ode15s
tic
[t15s, s15s] = ode15s(f, tspan, s0);
time15s = toc;
fprintf('ode15s: %.4f s, %d points\n', time15s, length(t15s));

% d) Compare final values
fprintf('ode45 final state: %.4f, %.4f\n', s45(end,1), s45(end,2));
fprintf('ode15s final state: %.4f, %.4f\n', s15s(end,1), s15s(end,2));

omega = 2;

% a) Parameterized ODE handle
f = @(t, s, alpha) [s(2); ...                          % ds1/dt = di/dt
                    -2 * alpha * s(2) - omega^2 * s(1)]; % ds2/dt

% b) Underdamped case
fUnder = @(t, s) f(t, s, 0.3);
tspan = [0 10];
s0 = [1; 0];
[t_u, s_u] = ode45(fUnder, tspan, s0);

% c) Overdamped case
fOver = @(t, s) f(t, s, 3);
[t_o, s_o] = ode45(fOver, tspan, s0);

% d) Plot both
figure
plot(t_u, s_u(:,1), 'b-', 'LineWidth', 1.5)
hold on
plot(t_o, s_o(:,1), 'r-', 'LineWidth', 1.5)
hold off
xlabel('Time (s)')
ylabel('Current i(t)')
legend('Underdamped (\alpha = 0.3)', 'Overdamped (\alpha = 3)', 'Location', 'best')
title('RLC Vessel-Wall Analog: Underdamped vs Overdamped')

% e) Count zero-crossings in each
crossings_u = sum(diff(sign(s_u(:,1))) ~= 0);
crossings_o = sum(diff(sign(s_o(:,1))) ~= 0);
fprintf('Underdamped zero-crossings: %d\n', crossings_u);
fprintf('Overdamped zero-crossings: %d\n', crossings_o);

kon = 500; koff = 500; kcat = 0.5;

% a) ODE handle
f = @(t, s) [-kon * s(1) + (koff + kcat) * s(2); ...   % dsubstrate/dt
              kon * s(1) - (koff + kcat) * s(2)];       % dcomplex/dt
s0 = [10; 0];
tspan = [0 20];

% b) Solve with ode45 (default tolerance)
tic
[t1, y1] = ode45(f, tspan, s0);
time45 = toc;
fprintf('ode45 (default tol): %.4f s, %d points\n', time45, length(t1));

% c) Solve with ode15s
tic
[t2, y2] = ode15s(f, tspan, s0);
time15s = toc;
fprintf('ode15s: %.4f s, %d points\n', time15s, length(t2));

% d) Solve with ode45, tightened tolerance
options = odeset('RelTol', 1e-6, 'AbsTol', 1e-9);
tic
[t3, y3] = ode45(f, tspan, s0, options);
time45_tight = toc;
fprintf('ode45 (tight tol): %.4f s, %d points\n', time45_tight, length(t3));

% e) Written explanation:
% This system is stiff because kon = koff = 500 sets a very fast
% timescale (binding equilibrium reached in roughly 1/500 = 0.002 time
% units) while kcat = 0.5 sets a much slower timescale (roughly 1/0.5 =
% 2 time units) for the actual catalytic conversion -- a 1000-fold
% separation between the two rates. Tightening ode45's tolerance in (d)
% barely changed the step count compared to (b), because ode45's step
% size here isn't limited by accuracy at all -- it's limited by numerical
% stability near the fast kon/koff dynamics, which forces small steps
% everywhere in the simulation regardless of how loose or tight the
% error tolerance is set. ode15s uses an implicit method that remains
% stable with much larger steps even when the fast mode is present,
% which is why it alone -- not a tighter tolerance -- closes the gap.

% a) Parameterized ODE handle
f = @(t, s, mu) [s(2); ...                       % ds1/dt
                 mu * (1 - s(1)^2) * s(2) - s(1)]; % ds2/dt
s0 = [2; 0];
tspan = [0 60];

% b) Solve for each mu value
mus = [0.5, 3, 15];
tAll = cell(1, numel(mus));
vAll = cell(1, numel(mus));
for k = 1:numel(mus)
    fk = @(t, s) f(t, s, mus(k));
    [tk, sk] = ode45(fk, tspan, s0);
    tAll{k} = tk;
    vAll{k} = sk(:, 1);
end

% c) Plot all three on the same axes
figure
hold on
for k = 1:numel(mus)
    plot(tAll{k}, vAll{k}, 'LineWidth', 1.5)
end
hold off
xlabel('Time (s)')
ylabel('Respiratory drive v(t)')
legend("\mu = " + string(mus), 'Location', 'best')
title('Van der Pol Respiratory Oscillator Across \mu')

% d) Estimate average period for each mu
avgPeriods = zeros(1, numel(mus));
for k = 1:numel(mus)
    v = vAll{k};
    t = tAll{k};
    peakTimes = t(islocalmax(v));
    avgPeriods(k) = mean(diff(peakTimes));
    fprintf('mu = %.1f: average period = %.2f s\n', mus(k), avgPeriods(k));
end

% e) Written description:
% At mu = 0.5, v(t) looks nearly sinusoidal, with a short, fairly
% constant period (roughly 6.4 s). As mu increases to 3, the waveform
% starts to distort and the period lengthens noticeably (roughly 8.9 s).
% By mu = 15, the waveform has become a clear relaxation oscillation:
% long, slow ramps punctuated by fast, sharp jumps between extremes, and
% the period has stretched to roughly 27 s -- more than four times
% longer than the mu = 0.5 case. A real respiratory drive signal rises
% and falls smoothly and fairly quickly (a normal breath cycle is a few
% seconds, not tens of seconds), so the mu = 15 regime no longer looks
% like a plausible model of breathing -- it's mathematically still a
% self-sustaining oscillator, but its sharp-jump-and-slow-ramp shape and
% greatly stretched period don't correspond to any real, healthy
% respiratory pattern.
